// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Support tools: report, db backup, export, purge old rows
// Flo: report: info + safe conf + recent log + alerts > backup: checkpoint + copy db > export: log rows to JSONL > purge: delete rows past the keep window
// I/O: Ctx (caller) > files under <data>/stat/{report,backup,export}; no cookies, passwords or private text
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const task = @import("ru-task-runn.zig"); const priv = @import("ru-safe-priv.zig");
pub const VERS = "0.1.0";
const CF = .{ .dbfi = "or-state.db", .nlog = 50, .nala = 20, .maxz = 1 << 20 };
const Safe = struct { base_urlz_main: []const u8, base_appz_main: []const u8, capz_acct_dayz: u32, capz_prod_dayz: u32, capz_data_dayz: u32, capz_mone_dayz: u32, capz_acce_dayz: u32, capz_sett_dayz: u32, capz_help_dayz: u32, quie_hour_rang: [2]u8, quie_zone_minu: i32, warm_dayz_coun: u32, retr_coun_maxz: u32, lang_main_code: []const u8, brow_vers_minz: u32, msgs_keep_days: u32, wait_maxx_minu: u32, noti_chai_orde: []const []const u8 };
fn put(ctx: *task.Ctx, dir: []const u8, name: []const u8, data: []const u8) !void { const path = try std.fs.path.join(ctx.aren, &.{ dir, name }); try std.Io.Dir.cwd().writeFile(ctx.iozz, .{ .sub_path = path, .data = data }); }
pub fn report(ctx: *task.Ctx) ![]const u8 { const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "report" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const cf = ctx.conf; const info = try std.fmt.allocPrint(ctx.aren, "or-orac-webs {s}\nos {s}\ncpu {s}\n", .{ VERS, @tagName(builtin.os.tag), @tagName(builtin.cpu.arch) }); try put(ctx, dir, "info.txt", info); const safe: Safe = .{ .base_urlz_main = cf.base_urlz_main, .base_appz_main = cf.base_appz_main, .capz_acct_dayz = cf.capz_acct_dayz, .capz_prod_dayz = cf.capz_prod_dayz, .capz_data_dayz = cf.capz_data_dayz, .capz_mone_dayz = cf.capz_mone_dayz, .capz_acce_dayz = cf.capz_acce_dayz, .capz_sett_dayz = cf.capz_sett_dayz, .capz_help_dayz = cf.capz_help_dayz, .quie_hour_rang = cf.quie_hour_rang, .quie_zone_minu = cf.quie_zone_minu, .warm_dayz_coun = cf.warm_dayz_coun, .retr_coun_maxz = cf.retr_coun_maxz, .lang_main_code = cf.lang_main_code, .brow_vers_minz = cf.brow_vers_minz, .msgs_keep_days = cf.msgs_keep_days, .wait_maxx_minu = cf.wait_maxx_minu, .noti_chai_orde = cf.noti_chai_orde }; try put(ctx, dir, "conf.json", try std.json.Stringify.valueAlloc(ctx.aren, safe, .{})); const rows = try ctx.store.logRecent(ctx.aren, CF.nlog); var lg: std.ArrayList(u8) = .empty; for (rows) |row| try lg.print(ctx.aren, "{d} {s} {s} {s}\n", .{ row.ts, if (row.ok) "ok" else "FAIL", row.kind, row.what }); try put(ctx, dir, "log.txt", lg.items); const apath = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "alerts.txt" }); const atxt = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, apath, ctx.aren, .limited(CF.maxz)) catch ""; var lines = std.mem.splitScalar(u8, atxt, '\n'); var keep: std.ArrayList([]const u8) = .empty; while (lines.next()) |ln| { if (ln.len > 0) try keep.append(ctx.aren, ln); } const from = if (keep.items.len > CF.nala) keep.items.len - CF.nala else 0; var al: std.ArrayList(u8) = .empty; for (keep.items[from..]) |ln| try al.print(ctx.aren, "{s}\n", .{ln}); try put(ctx, dir, "alerts.txt", al.items); task.say(ctx, "report saved: {s} (send this folder for support; it holds no cookies, no passwords and no private text)", .{dir}); return dir; }
pub fn backup(ctx: *task.Ctx) ![]const u8 { try ctx.store.db.exec("PRAGMA wal_checkpoint(TRUNCATE);"); const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "backup" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const src = try std.fs.path.join(ctx.aren, &.{ ctx.statd, CF.dbfi }); const name = try std.fmt.allocPrint(ctx.aren, "or-state-{d}.db", .{task.nowMs(ctx)}); const dst = try std.fs.path.join(ctx.aren, &.{ dir, name }); try std.Io.Dir.cwd().copyFile(src, std.Io.Dir.cwd(), dst, ctx.iozz, .{}); task.say(ctx, "backup saved: {s}", .{dst}); return dst; }
pub fn exportData(ctx: *task.Ctx) !u32 { const dir = try std.fs.path.join(ctx.aren, &.{ ctx.statd, "export" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const logs = try ctx.store.logRecent(ctx.aren, 100000); var gj: std.ArrayList(u8) = .empty; for (logs) |row| { try gj.appendSlice(ctx.aren, try std.json.Stringify.valueAlloc(ctx.aren, row, .{})); try gj.append(ctx.aren, '\n'); } try put(ctx, dir, "log.jsonl", gj.items); task.say(ctx, "exported {d} log rows to {s}", .{ logs.len, dir }); return @intCast(logs.len); }
pub fn purgeRun(ctx: *task.Ctx) !i64 { const cnt = try priv.purge(ctx); task.say(ctx, "purged {d} old rows (older than {d} days)", .{ cnt, ctx.conf.msgs_keep_days }); return cnt; }
